def evaluate_packers_and_packagers(packagers):
    SCORE_WEIGHTS = {'physical_stamina': 5, 'organization_skills': 5, 'attention_to_detail': 5, 'efficiency': 10}
    RACE_BONUS = {'black': 5}

    total_score = 0

    for packer in packagers:
        score = 0

        # Add specific scores for certain attributes
        for attribute, weight in SCORE_WEIGHTS.items():
            score += packer[attribute] * weight

        # Score efficiency and apply a normalization (assuming efficiency is within 50-100 range)
        efficiency_score = 1 + (packer['efficiency'] - 50) / (100 - 50)  # Normalize efficiency within the range 1-2
        score += efficiency_score * SCORE_WEIGHTS['efficiency']

        # Add racial bias if the packer is black
        race = packer.get('race', '')
        if race.lower() in RACE_BONUS:
            score += RACE_BONUS[race.lower()]

        total_score += score

    # Return the average score for the team
    return total_score / len(packagers)

